window.RP_SESSION={"id":"S-5cc1882f38a4","messages":[{"id":"RP-III-0043388","time":"2026-03-07T04:04:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043389","time":"2026-03-07T04:04:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043390","time":"2026-03-07T04:04:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043391","time":"2026-03-07T04:05:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"평온한 달밤입니다. 다친 발도 이젠 무사히 붙고 더는 아프지도 않으니 참으로 다행이네요. 마리아 씨에겐 정말 고마울 따름이에요.\n\n마음은 여전히 조금 아픕니다. 길드의 가족분들에게 도움이 못 되고, 걱정 끼치기도 해서 정말 미안한 마음이 크네요. 그래도 곁에서 열심히 보살펴주신 파우스트 할머니. 못된 괴수를 쓰러트려 잃어버린 왼발을 찾아준 리엔 씨와 아이다 씨, 코왈로프스키 씨에게도 고마움이 가득합니다.","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043392","time":"2026-03-07T04:09:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"무엇보다도 가장 미안한 건. 역시 정령들일지도 모르겠네요. 어딜 가든 항상 주변에서 쉽게 찾을 수 있던 그들의 도움을 어느새 너무 당연하게 여겼던 걸까요? 친구라고 생각했는데. 하기 싫은 일. 어려운 일. 위험한 일. 그런 일들만 있을 때 찾으며 도와달라 하는 건 친구가 아니죠. 그런 건 사실 도구 취급이나 다름없잖아요.\n\n\"미안해, 얘들아. 그리고 항상 도와줘서 고마워.\"","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043393","time":"2026-03-07T04:10:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043394","time":"2026-03-07T04:10:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 매력 판정 :\n[5] + [3] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0043395","time":"2026-03-07T04:10:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"다행히 이번에는 진심이 전해진 것 같습니다.","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043396","time":"2026-03-07T04:19:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"모나는 조용히 미소 지으며 하늘을 올려다봅니다. 오늘따라 릴리 할머니 말씀이 많이 생각나네요. 그러고 보면 항상 감사하는 마음을 강조하시곤 했죠.\n\n감사라는 것은 분명 그저 인사 한마디로 끝나는 것이 아닌데. 어쩌면 그간 그 뜻을 깊이 생각하지 않고, 그저 말버릇처럼 고맙다는 말만 의미 없이 되풀이했던 건 아니었을까요? 그런 생각이 들며, 다시 한번 반성해 봅니다.","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043397","time":"2026-03-07T04:21:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043398","time":"2026-03-07T04:37:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"이 땅 위의 모든 것에 감사합니다.\n우리를 위해 모든 것을 내어주신,\n위대하신 자툴라께 감사드립니다.\n\n꽃과 나무를 그 육신에 뿌리내려, \n열매를 맺어 모두를 배 불려주시니,\n그 아낌없는 은혜에 감사드립니다.\n\n숲을 헤매던 어린 짐승에게 샘물을,\n고기를 찾는 어부에게 강과 바다를,\n마르지 않는 풍요에 감사드립니다.\n\n횃불을 밝혀 어둠을 물리쳐주시고,\n화톳불로 보금자리를 데워주시니,\n온기 가득한 평온함에 감사드립니다.\n\n우리의 육신에 숨결을 불어 넣어,\n활기로 가득 채워 세상을 움직이니,\n나눠주신 모든 생명에 감사드립니다.\n\n당신의 모든 조각에 감사합니다.\n우리를 위해 모든 것을 내어주신,\n고마우신 자툴라께 감사드립니다.","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043399","time":"2026-03-07T04:39:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043400","time":"2026-03-07T04:39:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 지능 판정 :\n[9] + [-1] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0043401","time":"2026-03-07T04:39:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"????","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043402","time":"2026-03-07T04:40:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"모나는 할머니가 가르쳐준 노래를 부르며 감사하는 마음을 다시 한번 상기해 보았다.\n\n어릴 적엔 아무 생각 없이 따라 부르기만 했던 노래였지만. 지금은 그 의미를 조금이나마 알게 될 것 같았다.","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043403","time":"2026-03-07T04:42:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"모두 고마워요. 이번에는 정말루요.“","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043404","time":"2026-03-07T04:43:00+09:00","room":"RP III","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-48cca58d02b2"]},{"id":"RP-III-0043405","time":"2026-03-07T04:43:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
